#include <stdio.h>
#include <string.h>

int BF(const char *s, const char *t)
{
    int i = 0, j = 0;
    int n = strlen(s), m = strlen(t);
    while (i < n && j < m) {
        if (s[i] == t[j]) {
            i++;
            j++;
        } else {
            i = i - j + 1;
            j = 0;
        }
    }
    return j == m ? i - m + 1 : 0;
}

int main(void)
{
    char s[101], t[101];
    scanf("%s%s", s, t);
    printf("%d\n", BF(s, t));
    return 0;
}

#include <stdio.h>
#include <string.h>

void GetNext(const char *t, int next[])
{
    int j = 0, k = -1, m = strlen(t);
    next[0] = -1;
    while (j < m - 1) {
        if (k == -1 || t[j] == t[k]) {
            j++;
            k++;
            next[j] = k;
        } else
            k = next[k];
    }
}

int main(void)
{
    char s[101], t[101];
    int next[101], i, j = 0, n, m;
    scanf("%s%s", s, t);
    n = strlen(s);
    m = strlen(t);
    GetNext(t, next);
    for (i = 0; i < m; i++)
        printf("%d ", next[i]);
    printf("\n");
    i = 0;
    while (i < n && j < m) {
        if (j == -1 || s[i] == t[j]) {
            i++;
            j++;
        } else
            j = next[j];
    }
    printf("%d\n", j == m ? i - m + 1 : 0);
    return 0;
}
